mapper.select:
SELECT id, 0 AS workspaceId, object_key AS objectKey, attempts,
       delete_passes_remaining AS deletePassesRemaining
FROM user_object_deletion_queue
WHERE next_attempt_at <= #{now}
ORDER BY next_attempt_at, id
LIMIT #{limit}

mapper.update:
UPDATE user_object_deletion_queue
SET attempts = LEAST(attempts + 1, 2147483647), next_attempt_at = #{nextAttemptAt}
WHERE id = #{id}

UPDATE user_object_deletion_queue
SET attempts = LEAST(attempts + 1, 2147483647), next_attempt_at = #{nextAttemptAt}
WHERE object_key = #{objectKey}
